CREATE TABLE public.holiday_preferences (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, province text NOT NULL, available_from date NOT NULL, available_until date NOT NULL, festive_mode boolean NOT NULL DEFAULT true, CHECK (available_until >= available_from), CHECK (province IN ('Gauteng','Western Cape','KwaZulu-Natal','Eastern Cape','Free State','Limpopo','Mpumalanga','North West','Northern Cape')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.holiday_preferences TO authenticated; GRANT ALL ON public.holiday_preferences TO service_role;
ALTER TABLE public.holiday_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see holiday availability" ON public.holiday_preferences FOR SELECT TO authenticated USING (true);
CREATE POLICY "Own holiday availability" ON public.holiday_preferences FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE TABLE public.music_preferences (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, genres text[] NOT NULL DEFAULT '{}', artist text NOT NULL DEFAULT '', track text NOT NULL DEFAULT '', playlist_url text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.music_preferences TO authenticated; GRANT ALL ON public.music_preferences TO service_role;
ALTER TABLE public.music_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see music" ON public.music_preferences FOR SELECT TO authenticated USING (true);
CREATE POLICY "Own music" ON public.music_preferences FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE TABLE public.group_dates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), host uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 100), venue text NOT NULL CHECK (char_length(venue) BETWEEN 1 AND 200), province text NOT NULL CHECK (province IN ('Gauteng','Western Cape','KwaZulu-Natal','Eastern Cape','Free State','Limpopo','Mpumalanga','North West','Northern Cape')), starts_at timestamptz NOT NULL, capacity integer NOT NULL DEFAULT 4 CHECK (capacity BETWEEN 3 AND 12), cancelled boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.group_dates TO authenticated; GRANT ALL ON public.group_dates TO service_role;
ALTER TABLE public.group_dates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see group dates" ON public.group_dates FOR SELECT TO authenticated USING (true);
CREATE POLICY "Create own group date" ON public.group_dates FOR INSERT TO authenticated WITH CHECK (auth.uid()=host);
CREATE POLICY "Update own group date" ON public.group_dates FOR UPDATE TO authenticated USING (auth.uid()=host) WITH CHECK (auth.uid()=host);
CREATE TABLE public.group_date_members (date_id uuid NOT NULL REFERENCES public.group_dates(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(date_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.group_date_members TO authenticated; GRANT ALL ON public.group_date_members TO service_role;
ALTER TABLE public.group_date_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members see group attendance" ON public.group_date_members FOR SELECT TO authenticated USING (true);
CREATE POLICY "Join as myself" ON public.group_date_members FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id);
CREATE POLICY "Leave as myself" ON public.group_date_members FOR DELETE TO authenticated USING (auth.uid()=user_id);
CREATE FUNCTION public.validate_group_join() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g public.group_dates; BEGIN SELECT * INTO g FROM public.group_dates WHERE id=NEW.date_id FOR UPDATE; IF g.id IS NULL OR g.cancelled OR g.starts_at <= now() OR g.host=NEW.user_id THEN RAISE EXCEPTION 'This group date is not available to join'; END IF; IF (SELECT count(*) FROM public.group_date_members WHERE date_id=g.id) >= g.capacity-1 THEN RAISE EXCEPTION 'This group date is full'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_group_join BEFORE INSERT ON public.group_date_members FOR EACH ROW EXECUTE FUNCTION public.validate_group_join();
CREATE FUNCTION public.validate_group_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.starts_at <= now() THEN RAISE EXCEPTION 'Choose a future date'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_group_date BEFORE INSERT ON public.group_dates FOR EACH ROW EXECUTE FUNCTION public.validate_group_date();
CREATE TABLE public.relationship_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 100), anniversary date NOT NULL, story text NOT NULL DEFAULT '' CHECK (char_length(story)<=2000), shared boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.relationship_milestones TO authenticated; GRANT ALL ON public.relationship_milestones TO service_role;
ALTER TABLE public.relationship_milestones ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own or shared milestones" ON public.relationship_milestones FOR SELECT TO authenticated USING (auth.uid()=user_id OR shared);
CREATE POLICY "Own milestones" ON public.relationship_milestones FOR ALL TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id);
CREATE TABLE public.safety_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, path text NOT NULL, status text NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted','verified','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.safety_submissions TO authenticated; GRANT ALL ON public.safety_submissions TO service_role;
ALTER TABLE public.safety_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own safety submissions" ON public.safety_submissions FOR SELECT TO authenticated USING (auth.uid()=user_id);
CREATE POLICY "Submit own video" ON public.safety_submissions FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id AND status='submitted' AND split_part(path,'/',1)=auth.uid()::text);
CREATE POLICY "Withdraw own video" ON public.safety_submissions FOR DELETE TO authenticated USING (auth.uid()=user_id);
CREATE POLICY "Upload own safety video" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='safety-videos' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('mp4','webm','mov'));
CREATE POLICY "Read own safety video" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='safety-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Delete own safety video" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='safety-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
ALTER PUBLICATION supabase_realtime ADD TABLE public.holiday_preferences, public.music_preferences, public.group_dates, public.group_date_members, public.relationship_milestones, public.safety_submissions;